//! Файл: settings/catalog/dex_graph.rs
//! Что делает: настройки адаптера DEX решения 308 (задача t137) — «граф без ожидания»: фоновый владелец графа маршрутов,
//! предохранитель отставания снимка, сторож зависания, пауза перезапуска, периодическая полная пересборка со сверкой,
//! частота повтора уведомлений. Решение 310 (задача t141): dex.check_due_read_only — достоверность пулов циклами
//! проверок без записи в реестр (check/fresh.rs). Отдельный
//! файл: каталог dex.rs — общий для многих задач. Имена и области — по соглашениям dex.* (раздел «DEX», область
//! «площадка», только площадка DEX — .dex_venue()). Все необязательные, значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «DEX»).

use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 308 и 310. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static DEX_GRAPH: &[SettingDef] = &[
    d("DEX", "dex.graph_background", K::Bool, L::None, "да/нет", V, "Решение 308: граф маршрутов (dex.router_mode = graph, поиск циклов DEX ↔ DEX) строит ОДНА фоновая задача, а расчёт монеты берёт готовый снимок — не ждёт построения и сам граф не строит. Снимок обновляется по событию: изменился пул — пересчитываются только он и пулы, чей курс к USDT от него зависит (без обхода всех пулов). Цена всегда по свежему состоянию пулов из реестра (снимок даёт только набор пулов-рёбер), перед сделкой — сверка, как раньше. Полная пересборка с нуля — при запуске, смене настроек графа, переподключении лент пулов, по кнопке «Пересобрать граф» (экран «Площадки») и по dex.graph_verify_s; она сравнивается с накопительной картой, расхождение — Error и уведомление, действующим становится собранный с нуля. Нет или не задана — как раньше: граф строит сам расчёт (одно построение за раз)").dex_venue().optional(),
    d("DEX", "dex.graph_max_lag_ms", K::Integer, L::Positive, "мс", V, "Решение 308 (при dex.graph_background = да): последний рубеж. Снимок графа отстал от реестра пулов больше стольких мс (возраст самой старой ещё не учтённой записи) — маршрутов графа нет, котировки по классике; счётчик котировок и эпизодов (экран «Площадки», за час/сутки), запись журнала dex.graph на эпизод, уведомление dex.graph_stale. Не действует, пока идёт полная пересборка без накопительной карты, её доводка или пересборка после смены настроек графа (снимок отдаётся — цена всё равно по свежему состоянию пулов). Задавать по «наибольшему отставанию, которое видел расчёт в ступени А, за час» на экране с запасом; в штатной работе срабатывать не должен. Не задана — предохранителя нет").dex_venue().optional(),
    d("DEX", "dex.graph_hang_ms", K::Integer, L::Positive, "мс", V, "Решение 308 (ревью №2): сторож фоновой задачи графа — накопительный круг идёт дольше стольких мс или изменения реестра ждут дольше стольких мс вне круга, полной сборки и доводки — задача перезапускается (брошенная работа останавливается сама), уведомление dex.graph_owner_failed; полная сборка и доводка зависанием не считаются. До новой карты котировки берут действующий снимок. Не задана — сторож ловит только падение задачи").dex_venue().optional(),
    d("DEX", "dex.graph_retry_pause_s", K::Integer, L::Positive, "секунды", V, "Решение 308 (ревью №1): пауза перед перезапуском упавшей/зависшей фоновой задачи графа и перед повтором неудавшейся полной пересборки (кнопка «Пересобрать граф» — сразу). Не задана — перезапуск и повтор по следующему изменению реестра").dex_venue().optional(),
    d("DEX", "dex.graph_stage_b_max_ms", K::Integer, L::Positive, "мс", V, "Решение 308 (повторное ревью): предел ступени Б — котировки берут снимок без накопительного обновления (догоняющая полная сборка, её доводка, снимок на прежних настройках графа) дольше стольких мс (отсчёт — с начала работы фоновой задачи, пауза перезапуска не входит) — один перезапуск на ступень (пауза dex.graph_retry_pause_s, уведомление dex.graph_owner_failed без повторов); повторное превышение в той же ступени снимает льготу (снимок снова проверяется предохранителем dex.graph_max_lag_ms), уведомление dex.graph_stale, сборка продолжается — петли перезапусков нет. Задавать с запасом над наибольшей полной длительностью ступени Б (экран «Площадки», dex.graph_build). Не задана — предела нет").dex_venue().optional(),
    d("DEX", "dex.graph_verify_s", K::Integer, L::Positive, "секунды", V, "Решение 308 (при dex.graph_background = да): каждые столько секунд — полная пересборка графа с нуля в фоне и сверка с накопительной картой (пара → пулы и глубины): расхождение — Error dex.graph с перечнем отличий, уведомление dex.graph_mismatch, счётчик на экране «Площадки»; действующим в любом случае становится собранный с нуля снимок. Котировки во время пересборки идут на действующем снимке. Не задана — только при запуске, смене настроек графа, переподключении лент пулов и по кнопке").dex_venue().optional(),
    d("DEX", "dex.check_due_read_only", K::Bool, L::None, "да/нет", V, "Решение 310 (задача t141, живой замер 16.11.2026): циклы проверок пулов (сверка с квотером, крючки) при каждом проходе по реестру спрашивают «пул достоверен?» у всех пулов. Раньше это делалось записью в реестр: каждый пул отмечался изменённым для фонового графа маршрутов и рос номер версии реестра — один проход давал столько отметок, сколько пулов (13 457 на живом боте), и фоновый граф (dex.graph_background) пересчитывал почти весь реестр за круг, а при выключенном фоне и dex.router_mode = graph расчёт перестраивал граф после каждого такого прохода (граф строится заново на каждую новую версию реестра, решение 129). Да — достоверность читается без записи: отметок и роста версии от этой проверки нет, какие пулы проверяются — то же самое. Нет или не задана — как раньше. Необязательна").dex_venue().optional(),
    d("DEX", "dex.graph_alert_min_s", K::Integer, L::Positive, "секунды", V, "Решение 308: пока снимок графа отстаёт сверх dex.graph_max_lag_ms, уведомление dex.graph_stale повторяется не чаще, чем раз в столько секунд (первое — сразу); тот же срок — у повторов dex.graph_owner_failed и записи «полная пересборка не удалась» с той же причиной. Не задана — dex.graph_stale одно на эпизод, dex.graph_owner_failed — на каждый перезапуск, запись о сбое пересборки — при смене причины").dex_venue().optional(),
];
